<!--
  Ficheiro: src/components/iptv/StreamLinkManager.vue
  Tipo: Gestor Vue.
  Função: Lista, cria, edita, testa, ativa, torna principal e elimina fontes.
-->
<script setup lang="ts">
import { ref } from "vue";import { channelRepository,streamLinkRepository } from "@/domain/repositories";import type { ChannelRecord,StreamLinkRecord } from "@/types/records";import { protocolLabel,qualityLabel,streamStateLabel } from "@/domain/iptv/format";import StreamLinkEditDialog from "./StreamLinkEditDialog.vue";import StreamTestButton from "./StreamTestButton.vue";
const props=defineProps<{channel:ChannelRecord;links:StreamLinkRecord[]}>();const emit=defineEmits<{changed:[StreamLinkRecord[]];channelChanged:[ChannelRecord];play:[]}>();const edit=ref<StreamLinkRecord|null>(null),open=ref(false);function upsert(item:StreamLinkRecord){const next=props.links.some(x=>x.id===item.id)?props.links.map(x=>x.id===item.id?item:x):[...props.links,item];emit("changed",next);open.value=false;edit.value=null}async function toggle(item:StreamLinkRecord){upsert(await streamLinkRepository.update(item.id,{ativo:item.ativo===false}) as StreamLinkRecord)}async function primary(item:StreamLinkRecord){const updated=await streamLinkRepository.update(item.id,{prioridade:0}) as StreamLinkRecord;const channel=await channelRepository.update(props.channel.id,{url_stream:item.url}) as ChannelRecord;upsert(updated);emit("channelChanged",channel)}async function remove(item:StreamLinkRecord){if(!confirm(`Eliminar a fonte “${item.rotulo||item.url}”?`))return;await streamLinkRepository.delete(item.id);emit("changed",props.links.filter(x=>x.id!==item.id))}
</script>
<template><section class="stream-manager"><div class="section-heading"><div><p class="eyebrow">Fontes técnicas</p><h3>Links do canal</h3></div><div class="live-actions"><button class="button button-primary" type="button" @click="edit=null;open=true">Adicionar fonte</button><button class="button button-secondary" type="button" @click="emit('play')">▶ Reproduzir</button></div></div><p v-if="!links.length" class="field-hint">O canal usa apenas o stream principal.</p><article v-for="item in links" :key="item.id" class="stream-manager-row"><div><strong>{{item.rotulo||protocolLabel(item.tipo)}}</strong><small>{{qualityLabel(item.qualidade)}} · prioridade {{item.prioridade??1000}} · {{streamStateLabel(item.ultimo_estado)}}</small><code>{{item.url}}</code></div><div class="stream-manager-actions"><StreamTestButton :link="item" @tested="upsert"/><button class="button button-secondary" type="button" @click="edit=item;open=true">Editar</button><button class="button button-secondary" type="button" @click="primary(item)">Principal</button><button class="button button-secondary" type="button" @click="toggle(item)">{{item.ativo===false?'Ativar':'Desativar'}}</button><button class="button button-danger" type="button" @click="remove(item)">Eliminar</button></div></article><StreamLinkEditDialog :channel="channel" :link="edit" :open="open" @close="open=false;edit=null" @saved="upsert"/></section></template>
